rust_translation:
fn ts_type_to_csharp_type(ts_type: Option<&TsType>) -> &'static str {
    let ts_type = match ts_type {
        Some(t) => t,
        None => return "dynamic",
    };

    // TSStringKeyword -> string
    if let TsType::TsKeywordType(TsKeywordType { kind: TsKeywordTypeKind::TsStringKeyword, .. }) = ts_type {
        return "string";
    }

    // TSNumberKeyword -> double
    if let TsType::TsKeywordType(TsKeywordType { kind: TsKeywordTypeKind::TsNumberKeyword, .. }) = ts_type {
        return "double";
    }

    // TSBooleanKeyword -> bool
    if let TsType::TsKeywordType(TsKeywordType { kind: TsKeywordTypeKind::TsBooleanKeyword, .. }) = ts_type {
        return "bool";
    }

    // TSAnyKeyword -> dynamic
    if let TsType::TsKeywordType(TsKeywordType { kind: TsKeywordTypeKind::TsAnyKeyword, .. }) = ts_type {
        return "dynamic";
    }

    // TSArrayType -> List<T>
    if let TsType::TsArrayType(arr) = ts_type {
        let element_type = ts_type_to_csharp_type(Some(&arr.elem_type));
        return Box::leak(format!("List<{}>", element_type).into_boxed_str());
    }

    // TSTypeLiteral -> dynamic
    if let TsType::TsTypeLit(_) = ts_type {
        return "dynamic";
    }

    // TSTypeReference
    if let TsType::TsTypeRef(type_ref) = ts_type {
        if let TsEntityName::Ident(ident) = &type_ref.type_name {
            let type_name = ident.sym.as_ref();
            match type_name {
                "decimal" => return "decimal",
                "int" | "int32" => return "int",
                "int64" | "long" => return "long",
                "float" | "float32" => return "float",
                "float64" | "double" => return "double",
                "short" | "int16" => return "short",
                "byte" => return "byte",
                "Guid" => return "Guid",
                "DateTime" => return "DateTime",
                "DateOnly" => return "DateOnly",
                "TimeOnly" => return "TimeOnly",
                _ => return "dynamic",
            }
        }
        return "dynamic";
    }

    "dynamic"
}
